// tf-deploy-v7.js — ThemeFlex v2.7.0 New Files
// Deploys 11 new/updated files (v2.5.0–v2.7.0)
//
// HOW TO USE:
//   1. Go to: https://themeflex.de/wp-admin/appearance/theme-editor.php
//   2. Open DevTools → Console (F12)
//   3. Paste this entire script and press Enter
//   4. Wait ~90 seconds for all files to deploy
//   5. Check console for ✅ / ❌ messages

(async function tfDeployV7() {
  'use strict';
  const BASE = location.origin + '/wp-admin/theme-editor.php';
  let ok = 0, fail = 0;

  async function getNonce(file) {
    const r = await fetch(BASE + '?file=' + encodeURIComponent(file) + '&theme=themeflex', {credentials: 'same-origin'});
    const html = await r.text();
    const m = html.match(/id="_wpnonce" value="([^"]+)"/);
    return m ? m[1] : null;
  }

  async function saveFile(label, file, b64) {
    console.log('🔄 Deploying: ' + label);
    try {
      const nonce = await getNonce(file);
      if (!nonce) { console.error('❌ Nonce fail: ' + label); fail++; return; }
      const body = new URLSearchParams();
      body.append('_wpnonce', nonce);
      body.append('action', 'edit-theme-plugin-file');
      body.append('file', file);
      body.append('theme', 'themeflex');
      body.append('newcontent', atob(b64));
      body.append('scrollto', '0');
      const r = await fetch(BASE, {method: 'POST', credentials: 'same-origin', body});
      if (r.ok) { console.log('✅ ' + label); ok++; }
      else { console.error('❌ HTTP ' + r.status + ': ' + label); fail++; }
    } catch(e) {
      console.error('❌ Error: ' + label + ' — ' + e.message); fail++;
    }
  }

  const files = [
  ["README.txt", "themeflex/README.txt", ``],
  ["includes/class-skin-manager.php", "themeflex/includes/class-skin-manager.php", ``],
  ["includes/class-icons.php", "themeflex/includes/class-icons.php", ``],
  ["page-about.php", "themeflex/page-about.php", ``],
  ["page-agency.php", "themeflex/page-agency.php", ``],
  ["page-services.php", "themeflex/page-services.php", ``],
  ["page-saas-v2.php", "themeflex/page-saas-v2.php", ``],
  ["page-ecommerce.php", "themeflex/page-ecommerce.php", ``],
  ["page-restaurant.php", "themeflex/page-restaurant.php", ``],
  ["page-real-estate.php", "themeflex/page-real-estate.php", ``],
  ["page-mobile-app.php", "themeflex/page-mobile-app.php", ``]
  ];

  console.log('🚀 ThemeFlex v7 Deploy — ' + files.length + ' files');
  const t = Date.now();
  for (const [label, path, b64] of files) {
    await saveFile(label, path, b64);
  }
  const elapsed = ((Date.now() - t) / 1000).toFixed(1);
  console.log('');
  console.log('═══════════════════════════════════');
  console.log('✅ Done: ' + ok + '   ❌ Failed: ' + fail + '   (' + elapsed + 's)');
  console.log('Reload the theme editor to verify.');
})();
